      "type": "diagram",
      "svg": "<svg viewBox='0 0 1100 1100'><rect x='0' y='0' width='1100' height='1100' fill='#1a1a2e'/><text x='550' y='80' text-anchor='middle' font-size='28' fill='#ffffff'>The Evidence Confidence Pyramid</text><polygon points='550,150 850,380 250,380' fill='#8b5cf6'/><text x='550' y='290' text-anchor='middle' font-size='18' fill='#ffffff'>Systematic Reviews /</text><text x='550' y='315' text-anchor='middle' font-size='18' fill='#ffffff'>Meta-Analyses</text><polygon points='250,380 850,380 900,560 200,560' fill='#6366f1'/><text x='550' y='470' text-anchor='middle' font-size='18' fill='#ffffff'>Randomized Controlled Trials</text><polygon points='200,560 900,560 950,740 150,740' fill='#0ea5e9'/><text x='550' y='650' text-anchor='middle' font-size='18' fill='#ffffff'>Uncontrolled Pilot Studies</text><polygon points='150,740 950,740 1000,920 100,920' fill='#f59e0b'/><text x='550' y='830' text-anchor='middle' font-size='18' fill='#1a1a2e'>Case Reports and Anecdote</text><text x='550' y='970' text-anchor='middle' font-size='18' fill='#ffffff'>Read from the base up: confidence grows with replication.</text><text x='550' y='1000' text-anchor='middle' font-size='16' fill='#888'>Not a substitute for professional evaluation.</text></svg>",
